# Hindi / Gujarati for Class 10 Maths Ch 12 questions.json.
# Templates use {0}, {1}, ... for the formulas of the English text, in order.
# Steps of the form "<label> $...$ <unit>" are translated from the LEAD table.
import re
from tr_ch04_common import by_option, feedback, _ITEMS
from common_translations import is_math_only, by_template

_FORMULA = re.compile(r"\$[^$]+\$")
def fill(english, hi, gu):
    f = _FORMULA.findall(english)
    return hi.format(*f), gu.format(*f)

