add("ex12_2.q2", ("इंजीनियरिंग की एक छात्रा रचेल से एक पतली एल्यूमीनियम की शीट का प्रयोग करते हुए एक मॉडल बनाने को कहा गया जो एक ऐसे बेलन के आकार का हो जिसके दोनों सिरों पर दो शंकु जुड़े हुए हों। इस मॉडल का व्यास 3 cm है और इसकी लंबाई 12 cm है। यदि प्रत्येक शंकु की ऊँचाई 2 cm हो तो रचेल द्वारा बनाए गए मॉडल में अंतर्विष्ट हवा का आयतन ज्ञात कीजिए। (यह मान लीजिए कि मॉडल की आंतरिक और बाहरी विमाएँ लगभग बराबर हैं।)",
                  "ઇજનેરીની વિદ્યાર્થિની રેચલને પાતળા ઍલ્યુમિનિયમના પતરામાંથી એક મૉડેલ બનાવવા કહ્યું, જે નળાકાર આકારનું હોય અને તેના બંને છેડે બે શંકુ જોડેલા હોય. મૉડેલનો વ્યાસ 3 cm અને લંબાઈ 12 cm છે. જો દરેક શંકુની ઊંચાઈ 2 cm હોય, તો રેચલે બનાવેલા મૉડેલમાં રહેલી હવાનું ઘનફળ શોધો. (ધારો કે મૉડેલનાં અંદરનાં અને બહારનાં માપ લગભગ સરખાં છે.)"),
    {0: CYL_LEN})
fig("ex12_2.q2", "रचेल का मॉडल", "રેચલનું મૉડેલ")
add("ex12_2.q3", ("एक गुलाब जामुन में उसके आयतन की लगभग 30% चीनी की चाशनी है। 45 गुलाब जामुनों में लगभग कितनी चाशनी होगी, यदि प्रत्येक गुलाब जामुन एक बेलन के आकार का है जिसके दोनों सिरे अर्धगोलाकार हैं तथा इसकी लंबाई 5 cm और व्यास 2.8 cm है?",
                  "એક ગુલાબજાંબુમાં તેના ઘનફળની આશરે 30% ખાંડની ચાસણી હોય છે. જો દરેક ગુલાબજાંબુ બંને છેડે અર્ધગોલકવાળા નળાકારના આકારનું હોય અને તેની લંબાઈ 5 cm તથા વ્યાસ 2.8 cm હોય, તો 45 ગુલાબજાંબુમાં આશરે કેટલી ચાસણી હશે?"),
    {0: ("{0} cm; बेलन की लंबाई {1} cm।", "{0} cm; નળાકારની લંબાઈ {1} cm.")})
add("ex12_2.q4", ("एक कलमदान घनाभ के आकार की एक लकड़ी से बना है जिसमें कलम रखने के लिए चार शंक्वाकार गड्ढे बने हुए हैं। घनाभ की विमाएँ 15 cm × 10 cm × 3.5 cm हैं। प्रत्येक गड्ढे की त्रिज्या 0.5 cm है और गहराई 1.4 cm है। पूरे कलमदान में लकड़ी का आयतन ज्ञात कीजिए।",
                  "લાકડાનું એક પેન-સ્ટૅન્ડ લંબઘન આકારનું છે અને તેમાં પેન રાખવા ચાર શંકુ આકારના ખાડા છે. લંબઘનનાં માપ 15 cm × 10 cm × 3.5 cm છે. દરેક ખાડાની ત્રિજ્યા 0.5 cm અને ઊંડાઈ 1.4 cm છે. આખા પેન-સ્ટૅન્ડમાં લાકડાનું ઘનફળ શોધો."))
add("ex12_2.q5", ("एक बर्तन एक उल्टे शंकु के आकार का है। इसकी ऊँचाई 8 cm है और इसके ऊपरी सिरे (जो खुला हुआ है) की त्रिज्या 5 cm है। यह ऊपर तक पानी से भरा हुआ है। जब इस बर्तन में सीसे की कुछ गोलियाँ, जिनमें प्रत्येक 0.5 cm त्रिज्या वाला एक गोला है, डाली जाती हैं, तो इसमें से भरे हुए पानी का एक-चौथाई भाग बाहर निकल जाता है। बर्तन में डाली गई सीसे की गोलियों की संख्या ज्ञात कीजिए।",
                  "એક પાત્ર ઊંધા શંકુના આકારનું છે. તેની ઊંચાઈ 8 cm છે અને તેના ખુલ્લા ઉપલા છેડાની ત્રિજ્યા 5 cm છે. તે છલોછલ પાણીથી ભરેલું છે. જ્યારે 0.5 cm ત્રિજ્યાવાળા ગોલક આકારના સીસાના છરા પાત્રમાં નાખવામાં આવે છે, ત્યારે પાણીનો ચોથો ભાગ બહાર નીકળી જાય છે. પાત્રમાં નાખેલા છરાની સંખ્યા શોધો."))
add("ex12_2.q6", ("ऊँचाई 220 cm और आधार व्यास 24 cm वाले एक बेलन, जिस पर ऊँचाई 60 cm और त्रिज्या 8 cm वाला एक अन्य बेलन अध्यारोपित है, से लोहे का एक स्तंभ बना है। इस स्तंभ का द्रव्यमान ज्ञात कीजिए, जबकि दिया है कि 1 cm³ लोहे का द्रव्यमान लगभग 8 g होता है। ({0} लीजिए)",
                  "220 cm ઊંચાઈ અને 24 cm પાયાના વ્યાસવાળા નળાકાર પર 60 cm ઊંચાઈ અને 8 cm ત્રિજ્યાવાળો બીજો નળાકાર મૂકીને લોખંડનો એક થાંભલો બનાવ્યો છે. 1 cm³ લોખંડનું દળ આશરે 8 g હોય, તો થાંભલાનું દળ શોધો. ({0} લો)"),
    {2: ("{0} kg (लगभग)", "{0} kg (આશરે)")})
add("ex12_2.q7", ("एक ठोस में, ऊँचाई 120 cm और त्रिज्या 60 cm वाला एक शंकु सम्मिलित है, जो 60 cm त्रिज्या वाले एक अर्धगोले पर आरोपित है। इस ठोस को पानी से भरे हुए एक लंब वृत्तीय बेलन में इस प्रकार सीधा डाल दिया जाता है कि यह बेलन की तली को स्पर्श करे। यदि बेलन की त्रिज्या 60 cm है और ऊँचाई 180 cm है तो बेलन में शेष बचे पानी का आयतन ज्ञात कीजिए।",
                  "એક ઘનમાં 120 cm ઊંચાઈ અને 60 cm ત્રિજ્યાવાળો શંકુ છે, જે 60 cm ત્રિજ્યાવાળા અર્ધગોલક પર ઊભો છે. આ ઘનને પાણીથી ભરેલા લંબવૃત્તીય નળાકારમાં સીધો એવી રીતે મૂકવામાં આવે છે કે તે તળિયાને સ્પર્શે. જો નળાકારની ત્રિજ્યા 60 cm અને ઊંચાઈ 180 cm હોય, તો નળાકારમાં બાકી રહેલા પાણીનું ઘનફળ શોધો."))
add("ex12_2.q8", ("एक गोलाकार काँच के बर्तन की एक बेलन के आकार की गर्दन है जिसकी लंबाई 8 cm है और व्यास 2 cm है, जबकि गोलाकार भाग का व्यास 8.5 cm है। इसमें भरे जा सकने वाली पानी की मात्रा माप कर, एक बच्ची यह ज्ञात करती है कि इस बर्तन का आयतन 345 cm³ है। जाँच कीजिए कि उस बच्ची का उत्तर सही है या नहीं, यह मानते हुए कि उपरोक्त माप आंतरिक माप हैं और {0}।",
                  "કાચના એક ગોલકાકાર પાત્રને નળાકાર ગરદન છે, જેની લંબાઈ 8 cm અને વ્યાસ 2 cm છે; ગોલકાકાર ભાગનો વ્યાસ 8.5 cm છે. પાણી માપીને એક બાળકી શોધે છે કે પાત્રનું ઘનફળ 345 cm³ છે. ઉપરનાં માપને અંદરનાં માપ ગણીને અને {0} લઈને ચકાસો કે તે સાચી છે કે નહિ."),
    {2: ("कुल {0} cm³, अतः वह सही नहीं है: आयतन 346.51 cm³ है।", "કુલ {0} cm³, તેથી તે સાચી નથી: ઘનફળ 346.51 cm³ છે.")})
add("eg7", ("एक ठोस खिलौना एक अर्धगोले के आकार का है जिस पर एक लंब वृत्तीय शंकु अध्यारोपित है। इस शंकु की ऊँचाई 2 cm है और आधार का व्यास 4 cm है। इस खिलौने का आयतन ज्ञात कीजिए। यदि एक लंब वृत्तीय बेलन इस खिलौने के परिगत हो, तो बेलन और खिलौने के आयतनों का अंतर ज्ञात कीजिए। ({0} लीजिए)",
            "એક ઘન રમકડું અર્ધગોલકના આકારનું છે જેની ઉપર લંબવૃત્તીય શંકુ છે. શંકુની ઊંચાઈ 2 cm અને પાયાનો વ્યાસ 4 cm છે. રમકડાનું ઘનફળ શોધો. જો એક લંબવૃત્તીય નળાકાર રમકડાને બહારથી બરાબર ઢાંકે, તો નળાકાર અને રમકડાનાં ઘનફળનો તફાવત શોધો. ({0} લો)"),
    {0: ("{0} cm। अर्धगोला {1} cm³", "{0} cm. અર્ધગોલક {1} cm³"), 3: ("बेलन की त्रिज्या 2 cm और ऊँचाई {0} cm है: {1} cm³", "નળાકારની ત્રિજ્યા 2 cm અને ઊંચાઈ {0} cm છે: {1} cm³")})
